  "loc.src.data.alienecology.field.title.cbe2b47b0646": "Divert the Carrier",
  "loc.src.data.alienecology.field.title.cc2834e645b9": "Intercept Manifest",
  "loc.src.data.alienecology.field.title.cfc220fd0b12": "Clause Nine — Field Verification",
  "loc.src.data.alienecology.field.title.d6cd66119375": "Unregistered Biological Signature",
  "loc.src.data.alienecology.field.title.d918f059cedc": "Who Owns the Lights",
  "loc.src.data.alienecology.field.title.e96afd29d5ae": "Crew Absent, Air Intact",
  "loc.src.data.alienecology.field.title.e9eea7ca3766": "Claim Dispute — Living Site",
  "loc.src.data.alienecology.field.title.fb2a1be97b33": "One Occupant, Still Cycling",
  "loc.src.data.alienecology.field.title.fd4dd0e675f8": "Quarantine Audit — Deep Pocket",
  "loc.src.data.alienfauna.field.name.031d5ed04772": "Anchor Beast",
  "loc.src.data.alienfauna.field.name.0b6aa95dd46f": "Pilgrim Spine",
  "loc.src.data.alienfauna.field.name.0d9cd870a4db": "Black Sail",
  "loc.src.data.alienfauna.field.name.195077d57acf": "Needle Swarm",
  "loc.src.data.alienfauna.field.name.1ad6a51dcd9a": "Hull Leech",
