  "loc.src.data.frontierregions.east.field.name.178d3484710e": "Wake Glow",
  "loc.src.data.frontierregions.east.field.name.1aa3378384e7": "Shoal Shadow",
  "loc.src.data.frontierregions.east.field.name.1ce743b3ef89": "Triton Wake Lab",
  "loc.src.data.frontierregions.east.field.name.1de98eef33f9": "Nereid Shoal",
  "loc.src.data.frontierregions.east.field.name.1ea81364248f": "Shoal Cache",
  "loc.src.data.frontierregions.east.field.name.23d66880c72a": "Ice-Hull Wreck",
  "loc.src.data.frontierregions.east.field.name.2b58a6687ed0": "Below-Deck Cache",
