  "loc.src.data.frontierregions.east.field.name.49dbe03e1400": "Shoal Claim",
  "loc.src.data.frontierregions.east.field.name.541453910c73": "The Wake",
  "loc.src.data.frontierregions.east.field.name.548f21ef1f99": "The Tide-Locked Watcher",
