  "loc.src.systems.impulsecharges.field.text.1d24cabcb0bc": "No impulse charges in cargo",
  "loc.src.systems.impulsecharges.field.text.33e206fbd807": "Charge arming — {Math_ceil_rt_throwCdT}s",
