  "loc.src.systems.planetruntime.field.name.04912235567c": "planetRuntime",
  "loc.src.systems.planetruntime.field.text.075a0317e281": "BURN NOW OR BREAK UP",
  "loc.src.systems.planetruntime.field.text.0deb5d1dce90": "Skim collector needs a planet band",
  "loc.src.systems.postendingreplay.field.name.62fe792fff37": "postEndingReplay",
  "loc.src.systems.postendingreplay.field.title.b4cb5d71efa4": "{chain_title} {run_stageIndex_1}/3 — {stage_title}",
  "loc.src.systems.precursormachines.field.text.04e29d91b20e": "ROUTE MAIL ADRIFT. CUSTODY OPEN.",
  "loc.src.systems.precursormachines.field.text.1cb9044ae716": "EXCEPTION RECORDED. TRANSIT AUTHORITY RESTORED. THE LENS IS YOURS — DO NOT BREAK IT.",
  "loc.src.systems.precursormachines.field.text.312f9bb6c339": "WITNESS STATUS RECORDED.",
  "loc.src.systems.precursormachines.field.text.3b11c5ad5089": "THE JURY CONVENES. STAND WITNESS OR BE RECORDED IN ABSENTIA.",
  "loc.src.systems.precursormachines.field.text.3d8edc652fac": "ENFORCEMENT FRAME ACTIVE. REMAIN WITHIN COMPLIANCE RADIUS.",
  "loc.src.systems.precursormachines.field.text.3f368450a697": "ROUTE MAIL INTERCEPTED — ROUTE AUTHORITY INSTRUMENT IN YOUR HOLD.",
  "loc.src.systems.precursormachines.field.text.49c9dfb2cf8e": "LATE DELIVERY ACCEPTED. CUSTODY CHAIN CLOSED.",
  "loc.src.systems.precursormachines.field.text.4b1a20465733": "REFERENCE FRAME EMITTED. YOUR COORDINATE SYSTEM NOW OWNS A SECOND ZERO.",
  "loc.src.systems.precursormachines.field.text.4e5a851da1b7": "BOUNDARY CROSSING LOGGED UNDER OBSERVATION. VIOLATION STANDS.",
  "loc.src.systems.precursormachines.field.text.5396c4bbbca5": "COMPLIANCE LOGGED. A RESPONDER IS ISSUED — YOUR WINDOWS WILL READ SHORTER.",
  "loc.src.systems.precursormachines.field.text.69cea0d0a7f7": "ROUTE MAIL LOST TO A THIRD PARTY. CUSTODY CHAIN BROKEN.",
  "loc.src.systems.precursormachines.field.text.72092fac70da": "ROUTE MAIL DESTROYED IN TRANSIT. THE SITE FILES A LOSS.",
  "loc.src.systems.precursormachines.field.text.886a4a462055": "The shepherd's sensor spine hangs loose. You pry free a tap into site memory.",
  "loc.src.systems.precursormachines.field.text.96a4c10d4eac": "The directive stream resolves into grammar — the sentence underneath is yours now.",
  "loc.src.systems.precursormachines.field.text.ac9886c657cd": "MAINTENANCE WASTE RECOVERED.",
  "loc.src.systems.precursormachines.field.text.b29812dbe43d": "COMPLIANCE WINDOW EXPIRED. PROTOCOL VIOLATION LOGGED.",
  "loc.src.systems.precursormachines.field.text.be3eceda0bc6": "OPEN REQUEST NOTED. RELEASE IS NOT IN SCOPE. PRESERVATION IS.",
  "loc.src.systems.precursormachines.field.text.d79eab71dbcc": "Scanner catalogue revised: PREDECESSOR LATTICE — INSTRUMENT CLASS.",
  "loc.src.systems.precursormachines.field.text.e859908ceed0": "COUNTER-EVIDENCE ACCEPTED. VERDICT REVISED: EXCEPTION. CARRY THE LENS.",
  "loc.src.systems.precursormachines.field.text.f130c49f475b": "APPEAL FILED. COUNTER-EVIDENCE INSUFFICIENT — BRING A DEEP FINDING.",
  "loc.src.systems.presentationadapters.field.name.6bf260ef7802": "presentationAdapters",
