  "loc.src.systems.salvage.field.name.b302dd402b5c": "salvage",
  "loc.src.systems.salvage.field.text.27d1eaeff784": "Delivery short: {lost}u scored. That is {repairEstimateCr} cr of core repair you are eating.",
  "loc.src.systems.salvage.field.text.61586b0df3e8": "A dead communicator drifts silent in the wreckage.",
  "loc.src.systems.salvage.field.text.6f36820afab7": "Signal recovered — {mission_giver}: \"{truncate_mission_log_80}\"",
  "loc.src.systems.salvage.field.text.709bff133256": "CLAMP SHEARED — the drive core is loose. Cradle marks the drop.",
  "loc.src.systems.salvage.field.text.db6d4c5074a0": "Core scored by debris — integrity {Math_round_pocket_integrity_100}%.",
  "loc.src.systems.salvageactions.field.name.4a767d86dda1": "salvageActions",
  "loc.src.systems.salvageactions.field.text.367a7033b85c": "The hot core lit the row — chain reaction.",
  "loc.src.systems.salvageactions.field.text.56dce853c53c": "The reactor's cooking off — clear it or use it.",
  "loc.src.systems.salvageactions.field.text.6a6f5877908c": "Core ejected — critical in {REACTOR_CORE_HOT_S}s. Scoop it or clear the blast.",
  "loc.src.systems.salvageactions.field.text.73931216b628": "Reactor's cooking — the crew is clearing the wreck!",
  "loc.src.systems.salvageactions.field.text.7f6dc024d1ad": "The vented core is going critical — scoop it or clear the blast!",
  "loc.src.systems.salvageactions.field.text.9c0aa980aa19": "Chain reaction — the whole row is going up.",
  "loc.src.systems.salvageactions.field.text.9feb939c9f69": "Reactor's going — clear the wreck!",
  "loc.src.systems.scanner.field.label.3339a7fa2b5d": "HAIL",
