  "loc.src.systems.scanner.field.text.165ba032cc3a": "Scanner recharging — {left}s",
  "loc.src.systems.scanreveal.field.name.712df72e8302": "scanReveal",
  "loc.src.systems.scavengeroccupationswitch.field.label.a0f9e2462918": "Redistributed salvage",
  "loc.src.systems.scavengeroccupationswitch.field.text.63a1490dedf6": "The wreck field's picker crew switched to hauling their hold in.",
  "loc.src.systems.scenarioruntime.field.name.f61f1abef193": "scenarioRuntime",
  "loc.src.systems.scenarioruntime.field.text.c6fcb428e886": "Cut the line and drift clear. Refuse, and we close in after twelve seconds.",
