  "loc.src.ui.impoundpayprompt.field.detail.227ac7eb9430": "The bill stands at {owed} cr — pay it here, work the yard, or cut the lock.${short ?",
  "loc.src.ui.impoundpayprompt.field.headline.507068241cb1": "FINE {amount} CR",
  "loc.src.ui.impoundpayprompt.field.headline.8fc593ab1f60": "RELEASE THE SHIP",
  "loc.src.ui.impoundpayprompt.field.label.19c4b1cb4f1d": "PAY {owed} CR",
  "loc.src.ui.impoundpayprompt.field.label.1d02d3cf7f62": "PAY {amount} CR",
  "loc.src.ui.impoundpayprompt.field.label.3b4a20407280": "WORK THE DEBT",
  "loc.src.ui.impoundpayprompt.field.label.41dd261655f6": "STEP AWAY",
  "loc.src.ui.impoundpayprompt.field.label.ccd2196084a7": "CARRY THE WARRANT",
  "loc.src.ui.impoundpayprompt.field.name.0d459e86087c": "impoundPayPrompt",
  "loc.src.ui.impoundpayprompt.field.text.7473f05a28ba": "SHORT — the fine is {p_amount_null_p_amount} cr. Work the shift or carry the warrant.",
  "loc.src.ui.impoundpayprompt.field.text.a2809347aa46": "SHORT — the bill is {p_owedCr_null_p_owedCr} cr and you hold {p_credits_null_p_credits} cr. Work the yard, or cut the lock.",
  "loc.src.ui.impoundpayprompt.field.text.ba71586e748b": "FINE ASSESSED — {Math_max_0_Math_round_Number_p_amount_0} cr on a {p_wantedTier_wanted} warrant. The desk takes your answer on the lane.",
  "loc.src.ui.impoundpayprompt.field.text.c8b4c5b30b5c": "The clerk is out of reach — nothing was charged.",
  "loc.src.ui.impoundpayprompt.field.text.ee67336b5584": "No open fine at that berth — nothing was charged.",
  "loc.src.ui.impoundpayprompt.field.title.189f79baef6c": "Close the counter. The yard shift and the lock stay open as ways out.",
  "loc.src.ui.impoundpayprompt.field.title.4daebc0e4559": "Wire the desk its fine — the warrant clears. The engine re-checks credits; a short account is refused, never charged.",
  "loc.src.ui.impoundpayprompt.field.title.529c4db05f73": "Hand the clerk the bill amount — the hull is released where it stands. The engine re-checks reach and credits; nothing is charged twice.",
  "loc.src.ui.impoundpayprompt.field.title.bd2109d76b97": "A short lawful shift accrues against the bill — no credits needed, just the clock.",
  "loc.src.ui.impoundpayprompt.field.title.f8c762698bf9": "Walk away. The warrant stands and the next lawful dock assesses it again.",
  "loc.src.ui.input.field.text.21e81fdf74ec": "{interactionDisplayName_wreck} is salvage, not an asteroid.",
  "loc.src.ui.input.field.text.3c22e21373a0": "Claim record not ready — try again in a moment",
  "loc.src.ui.input.field.text.5bee93e71e6b": "Too far to drill. Fly closer to the asteroid.",
  "loc.src.ui.input.field.text.67debf880d98": "No dock prompt active",
  "loc.src.ui.input.field.text.68ef292b5580": "Base screen is still loading — press {BINDINGS_claimBase_label} again in a moment",
  "loc.src.ui.input.field.text.73839e8854e9": "No asteroid targeted — target a rock and press {BINDINGS_drill_label} to drill",
  "loc.src.ui.input.field.text.7fca54f6cf8f": "This legacy Massline has no drill winch. Relatch with the standard Massline to drill.",
  "loc.src.ui.input.field.text.999b7e1c1ff5": "No Massline link. {latchHint}",
  "loc.src.ui.input.field.text.eb99532bd392": "Hazardous reactor wreck — it explodes when its reactor timer runs out.",
