  "loc.src.ui.powerrail.field.description.0d3e3009cb2e": "toggle the scoop sheet and harvest by grazing a planet band",
  "loc.src.ui.powerrail.field.description.1719f1d2129b": "release the selected drift bomb at ship velocity",
  "loc.src.ui.powerrail.field.description.299e2e83802f": "{dry_name} ×0. {dry_sentence} {armedCount} armed; {fields} active fields. Friendly fire applies.",
